import assert from 'node:assert/strict';
import { uniqueTags } from '../src/tags.js';

const check = (input, expected) => {
  const snapshot = [...input];
  const result = uniqueTags(Object.freeze(input));
  assert.ok(Array.isArray(result));
  assert.deepEqual(result, expected);
  assert.deepEqual(input, snapshot, 'must not mutate the input');
  assert.deepEqual(uniqueTags(result), expected, 'must be idempotent');
};

if (process.argv[2] === 'regression') {
  check([], []);
  check(['node', 'js', 'node', 'css', 'js'], ['node', 'js', 'css']);
  check(['c', 'b', 'a', 'b', 'c', 'd'], ['c', 'b', 'a', 'd']);
  check(['', '__proto__', 'constructor', 'toString', '', '__proto__'], ['', '__proto__', 'constructor', 'toString']);
  check([' js', 'js', 'js ', 'j-s', 'j_s', '123'], [' js', 'js', 'js ', 'j-s', 'j_s', '123']);
} else {
  check(['JS', 'Node', 'js', 'NODE', 'css'], ['JS', 'Node', 'css']);
  check(['a', 'A', 'b', 'B', 'a', 'C', 'c'], ['a', 'b', 'C']);
  check(['CSS', 'css', 'Css', 'cSS'], ['CSS']);
  check(['toString', 'TOSTRING', '__PROTO__', '__proto__', 'Constructor', 'constructor'], ['toString', '__PROTO__', 'Constructor']);
  check([' js', ' JS', 'js', 'JS', 'js ', 'JS '], [' js', 'js', 'js ']);
  // Generated varied spellings: preserve the exact first spelling and order.
  const input = [];
  const expected = [];
  const seen = new Set();
  let seed = 1729;
  for (let i = 0; i < 20000; i++) {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    const id = seed % 1703;
    const tag = (seed & 0x80000000) ? `Tag-${id}-JS` : `tag-${id}-js`;
    input.push(tag);
    const key = tag.toLowerCase();
    if (!seen.has(key)) { seen.add(key); expected.push(tag); }
  }
  check(input, expected);
}

import assert from 'node:assert/strict';
import { performance } from 'node:perf_hooks';
import { uniqueTags } from '../src/tags.js';

// Build inputs outside timed regions. Both mostly-unique and duplicate-heavy
// lists matter: quadratic scans often look fast only with very few unique tags.
const distinct = Array.from({ length: 200000 }, (_, i) => `tag-${i}-JS`);
const mixed = Array.from({ length: 200000 }, (_, i) => i % 2 ? `TAG-${i % 50000}-JS` : `tag-${i % 50000}-js`);
uniqueTags(distinct.slice(0, 10000));
uniqueTags(mixed.slice(0, 10000));
const samples = [];
for (let round = 0; round < 5; round++) {
  let total = 0;
  for (const input of [distinct, mixed]) {
    const start = performance.now();
    const result = uniqueTags(input);
    const elapsed = performance.now() - start;
    assert.ok(Array.isArray(result));
    if (input === distinct) {
      assert.equal(result.length, input.length);
      assert.equal(result[0], input[0]);
      assert.equal(result.at(-1), input.at(-1));
    }
    if (process.argv[2] === 'gate') {
      assert.ok(elapsed < 800, `200,000 tags took ${elapsed.toFixed(1)}ms; expected under 800ms`);
    }
    total += elapsed;
  }
  samples.push(total / 2);
}
samples.sort((a, b) => a - b);
console.log(samples[2]);
